MS.hook('theme:colors', function (colors) {
  try {
    var c = colors || {};
    var bg = String(c.bg || '').trim();
    var lum = 1;
    if (/^#[0-9a-f]{3}$/i.test(bg)) {
      bg = '#' + bg.charAt(1) + bg.charAt(1) + bg.charAt(2) + bg.charAt(2) + bg.charAt(3) + bg.charAt(3);
    }
    if (/^#[0-9a-f]{6}$/i.test(bg)) {
      var r = parseInt(bg.slice(1, 3), 16);
      var g = parseInt(bg.slice(3, 5), 16);
      var b = parseInt(bg.slice(5, 7), 16);
      lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
    } else if (/^rgba?\(/i.test(bg)) {
      var mm = bg.match(/(\d+)[,\s]+(\d+)[,\s]+(\d+)/);
      if (mm) lum = (0.299 * +mm[1] + 0.587 * +mm[2] + 0.114 * +mm[3]) / 255;
    }
    if (lum > 0.5) return colors;
    return {
      bg: '#05070d',
      bg2: '#0b1220',
      bg3: '#141c2b',
      txt: '#e8eefc',
      sub: '#93a4c0',
      border: '#1f2a3d',
      primary: c.primary,
      primary2: c.primary2,
      success: c.success,
      warn: c.warn,
      danger: c.danger
    };
  } catch (e) {
    return colors;
  }
});
